package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class ArrayUtils_add_TriageGen4Test {

    @Test
    public void testAdd_StringArray_Middle() {
        String[] input = {"A", "C"};
        String[] expected = {"A", "B", "C"};
        String[] result = ArrayUtils.add(input, 1, "B");
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_StringArray_Start() {
        String[] input = {"B", "C"};
        String[] expected = {"A", "B", "C"};
        String[] result = ArrayUtils.add(input, 0, "A");
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_StringArray_End() {
        String[] input = {"A", "B"};
        String[] expected = {"A", "B", "C"};
        String[] result = ArrayUtils.add(input, 2, "C");
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_NullArray_WithElement() {
        // If array is null, it uses the element's class to create the new array
        String[] result = ArrayUtils.add(null, 0, "A");
        String[] expected = {"A"};
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_NullArray_And_NullElement() {
        // This hits the branch: else { return (T[]) new Object[] { null }; }
        // Note: The return type is T[], but the code returns an Object[] containing null.
        // In practice, this usually results in an array of size 1 containing null.
        Object[] result = ArrayUtils.add(null, 0, null);
        assertEquals(1, result.length);
        assertNull(result[0]);
    }

    @Test
    public void testAdd_IntegerArray() {
        Integer[] input = {1, 3};
        Integer[] expected = {1, 2, 3};
        Integer[] result = ArrayUtils.add(input, 1, 2);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_EmptyArray() {
        String[] input = {};
        String[] expected = {"A"};
        String[] result = ArrayUtils.add(input, 0, "A");
        assertArrayEquals(expected, result);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testAdd_IndexOutOfBounds() {
        String[] input = {"A", "B"};
        // index 5 is out of bounds for an array of size 2 (max valid index for add is 2)
        ArrayUtils.add(input, 5, "C");
    }

    @Test
    public void testAdd_MaintainsType() {
        // Verify that the returned array is of the correct component type
        Integer[] input = {1, 2};
        Integer[] result = ArrayUtils.add(input, 1, 3);
        assertSame(Integer[].class, result.getClass());
    }
}
